INSERT INTO "events" VALUES(1,NULL,'mykhailo','MyPc-chat','goal','Easy Paper — KMP-приложение (Android, Desktop, Web/Wasm, Ktor-сервер): врач собирает из виджетов запрос под жалобу, пациент несколько дней заполняет его текстом, числами и фото (еда, упаковки лекарств), а на приёме передаёт через QR зашифрованный отчёт, который ИИ сжимает в сводку со ссылками на оригиналы и предзаполненную форму клиники. Экономный ИИ-конвейер (штрих-код/OCR без LLM, маленькая модель для простого, большая один раз на сводку, кэш, учёт токенов и цены) и режим локального ИИ-модуля в клинике (Ollama). Приложение не ставит диагнозов и не советует — только собирает и структурирует факты; ИИ пишет черновик, каждое поле подтверждает врач.
INSERT INTO "events" VALUES(2,1,'mykhailo','MyPc-chat','created','Каркас KMP (Android, Desktop, Web/Wasm, Server/Ktor) по шаблону kmp.jetbrains.com + test.py (gradlew.bat или ./gradlew по ОС, desktopTest и тесты сервера) + teamhub.json {"test": "python test.py"} + закоммитить .claude/skills (frontend-design, easy-paper-design) [JB]','{"assignee":"mykhailo","criteria":"python test.py зелёный на Windows и Linux, Desktop и Android запускаются","title":"Каркас KMP (Android, Desktop, Web/Wasm, Server/Ktor) по шаблону kmp.jetbrains.com + test.py (gradlew.bat или ./gradlew по ОС, desktopTest и тесты сервера) + teamhub.json {\"test\": \"python test.py\"} + закоммитить .claude/skills (frontend-design, easy-paper-design) [JB]"}','2026-11-21T14:45:12+00:00');
INSERT INTO "events" VALUES(3,2,'mykhailo','MyPc-chat','created','Модель виджетов и данных в commonMain: схема запроса врача (список виджетов: опросник, давление, вода, еда, лекарства, дневник, вопросы врачу), ответы, зашифрованное локальное хранилище; формат схемы зафиксировать первым коммитом [JB][IMC]','{"assignee":"vlad","criteria":"тесты commonTest","title":"Модель виджетов и данных в commonMain: схема запроса врача (список виджетов: опросник, давление, вода, еда, лекарства, дневник, вопросы врачу), ответы, зашифрованное локальное хранилище; формат схемы зафиксировать первым коммитом [JB][IMC]"}','2026-11-21T14:45:13+00:00');
INSERT INTO "events" VALUES(4,3,'mykhailo','MyPc-chat','created','Дизайн-система: docs/design.md по навыкам frontend-design + easy-paper-design (палитра light/dark, шрифты, шкала, формы, принципы, ASCII-вайрфреймы «Сегодня» пациента и сводки врача) → показать mykhailo → EasyPaperTheme в commonMain [JB]','{"assignee":"mykhailo","criteria":"mykhailo утвердил docs/design.md, тема работает в light/dark","title":"Дизайн-система: docs/design.md по навыкам frontend-design + easy-paper-design (палитра light/dark, шрифты, шкала, формы, принципы, ASCII-вайрфреймы «Сегодня» пациента и сводки врача) → показать mykhailo → EasyPaperTheme в commonMain [JB]"}','2026-11-21T14:45:13+00:00');
INSERT INTO "events" VALUES(5,4,'mykhailo','MyPc-chat','created','UI пациента (Compose): все виджеты, фото по желанию, дневник, вопросы врачу, EN/DE/UK [JB][IMC][AXA] [старт после утверждённого docs/design.md]','{"assignee":"pavlo","criteria":"работает на Android и Desktop, только токены темы","title":"UI пациента (Compose): все виджеты, фото по желанию, дневник, вопросы врачу, EN/DE/UK [JB][IMC][AXA] [старт после утверждённого docs/design.md]"}','2026-11-21T14:45:13+00:00');
INSERT INTO "events" VALUES(6,5,'mykhailo','MyPc-chat','created','Конструктор запроса врача (Web + Desktop): виджеты + срок → приглашение (ссылка/QR) [JB][IMC] [старт после утверждённого docs/design.md]','{"assignee":"pavlo","criteria":"пациент открывает и видит ровно эти виджеты","title":"Конструктор запроса врача (Web + Desktop): виджеты + срок → приглашение (ссылка/QR) [JB][IMC] [старт после утверждённого docs/design.md]"}','2026-11-21T14:45:13+00:00');
INSERT INTO "events" VALUES(7,6,'mykhailo','MyPc-chat','created','Скан лекарств: штрих-код/DataMatrix + OCR → локальная база-подмножество → подтверждение [AXA]','{"assignee":"vlad","criteria":"10+ препаратов распознаются","title":"Скан лекарств: штрих-код/DataMatrix + OCR → локальная база-подмножество → подтверждение [AXA]"}','2026-11-21T14:45:13+00:00');
INSERT INTO "events" VALUES(8,7,'mykhailo','MyPc-chat','created','ИИ-конвейер в commonMain: общий интерфейс, провайдеры OpenRouter и Ollama, сжатие фото, маленькая модель для простого, большая один раз для сводки со ссылками на оригиналы, кэш, учёт токенов и цены [AXA][JB]','{"assignee":"mykhailo","criteria":"тесты на моках","title":"ИИ-конвейер в commonMain: общий интерфейс, провайдеры OpenRouter и Ollama, сжатие фото, маленькая модель для простого, большая один раз для сводки со ссылками на оригиналы, кэш, учёт токенов и цены [AXA][JB]"}','2026-11-21T14:45:14+00:00');
INSERT INTO "events" VALUES(9,8,'mykhailo','MyPc-chat','created','Ktor-сервер в двух режимах: облачный (прокси, ключ только на сервере, лимит бюджета, слепой релей отчётов) и «клиника» (Ollama, загрузка документов, предзаполнение формы) [JB][AXA]','{"assignee":"mykhailo","criteria":"тесты сервера","title":"Ktor-сервер в двух режимах: облачный (прокси, ключ только на сервере, лимит бюджета, слепой релей отчётов) и «клиника» (Ollama, загрузка документов, предзаполнение формы) [JB][AXA]"}','2026-11-21T14:45:14+00:00');
INSERT INTO "events" VALUES(10,9,'mykhailo','MyPc-chat','created','Отчёт и передача: сводка + FHIR-подобный JSON, шифрование, QR с ключом; формат отчёта зафиксировать первым коммитом [IMC][JB]','{"assignee":"vlad","criteria":"без ключа не расшифровать","title":"Отчёт и передача: сводка + FHIR-подобный JSON, шифрование, QR с ключом; формат отчёта зафиксировать первым коммитом [IMC][JB]"}','2026-11-21T14:45:14+00:00');
INSERT INTO "events" VALUES(11,10,'mykhailo','MyPc-chat','created','Экран врача на приёме: сводка → оригиналы; предзаполненная форма с подтверждением каждого поля [IMC][JB] [старт после утверждённого docs/design.md]','{"assignee":"pavlo","criteria":"демо-отчёт открывается, без подтверждения ничего не сохраняется","title":"Экран врача на приёме: сводка → оригиналы; предзаполненная форма с подтверждением каждого поля [IMC][JB] [старт после утверждённого docs/design.md]"}','2026-11-21T14:45:14+00:00');
INSERT INTO "events" VALUES(12,11,'mykhailo','MyPc-chat','created','Демо и презентация: облако против локального модуля по цене, общий/платформенный код, скриншоты агентов в Air [JB][IMC][AXA]','{"assignee":"mykhailo","criteria":"сценарий на 3 минуты","title":"Демо и презентация: облако против локального модуля по цене, общий/платформенный код, скриншоты агентов в Air [JB][IMC][AXA]"}','2026-11-21T14:45:14+00:00');
